const raw = $json.body ?? $json;

function getField(candidates, fallback = '') {
  const entries = Object.entries(raw).map(([key, value]) => [String(key).trim().toLowerCase(), value]);
  for (const candidate of candidates) {
    const normalized = candidate.trim().toLowerCase();
    const found = entries.find(([key]) => key === normalized);
    if (found) return found[1];
  }
  return fallback;
}

function text(value) {
  return String(value ?? '').trim();
}

function money(value) {
  const numeric = text(value).replace(/[^0-9.]/g, '');
  return numeric ? Number(numeric) : 0;
}

function list(value) {
  if (Array.isArray(value)) return value.map(text).filter(Boolean);
  return text(value).split(/[,;|]/).map(text).filter(Boolean);
}

const name = text(getField(['full name', 'name', 'customer name'], 'New buyer'));
const email = text(getField(['email', 'email address']));
const phone = text(getField(['phone', 'phone number', 'whatsapp', 'mobile']));
const productInterest = text(getField(['product interest', 'item', 'items', 'interested item', 'collection']));
const category = text(getField(['category', 'style category'], 'Fashion & lifestyle'));
const budget = money(getField(['budget', 'price range', 'target budget', 'spend']));
const preferredSizes = list(getField(['size', 'sizes', 'preferred size']));
const styleTags = list(getField(['style', 'style preference', 'occasion', 'vibe']));
const urgencyRaw = text(getField(['urgency', 'when do you need it', 'timeline'], 'browsing')).toLowerCase();
const source = text(getField(['source', 'how did you hear about us'], 'Interest form'));
const notes = text(getField(['notes', 'message', 'special request']));

const highIntentWords = ['today', 'now', 'urgent', 'this week', 'asap', 'ready', 'checkout'];
const highIntent = highIntentWords.some((word) => urgencyRaw.includes(word)) || budget >= 150;
const hasContact = Boolean(email || phone);
const missingSizeFlag = preferredSizes.length ? '' : 'Missing size preference - stylist follow-up needed';
const missingContactFlag = hasContact ? '' : 'Missing contact details - cannot follow up';
const segment = highIntent ? 'Ready-to-buy' : budget >= 75 ? 'Warm lead' : 'Browsing';
const priority = highIntent ? 'High' : budget >= 75 ? 'Medium' : 'Standard';
const recommendedAction = highIntent ? 'Send personal shopping offer' : 'Send lookbook and save for nurture';
const status = hasContact ? 'Follow-up queued' : 'Saved for review';
const randomDelayMinutes = Math.floor(Math.random() * 111) + 10;

return [{
  json: {
    submittedAt: new Date().toISOString(),
    name,
    email,
    phone,
    productInterest,
    category,
    budget,
    preferredSizes: preferredSizes.join(', '),
    styleTags: styleTags.join(', '),
    urgency: urgencyRaw || 'browsing',
    source,
    notes,
    segment,
    priority,
    highIntent,
    hasContact,
    status,
    recommendedAction,
    flags: [missingSizeFlag, missingContactFlag].filter(Boolean).join('; '),
    randomDelayMinutes
  }
}];
